element.reference_qual:
javascript:(function() {                                                                                                                                                                                
      // Get the Sync Filter reference from current record                                                                                                                                                
      var syncFilterId = current.illumio_sync_filter;                                                                                                                                                     
                                                                                                                                                                                                          
      // If no Sync Filter selected, show nothing                                                                                                                                                         
      if (gs.nil(syncFilterId)) {
          return 'sys_idISEMPTY';                                                                                                                                                                         
      }                                                                                                                                                                                                   
   
      // Look up the Sync Filter to get its PCE Configuration                                                                                                                                             
      var syncFilterGr = new GlideRecord('x_illu2_illumio_illumio_sync_filter');
      if (syncFilterGr.get(syncFilterId)) {                                                                                                                                                               
          var pceConfigId = syncFilterGr.getValue('pce_configuration');
                                                                                                                                                                                                          
          // Return query to filter Class Mappings by PCE Configuration                                                                                                                                   
          return 'illumio_pce_configuration=' + pceConfigId;
      }                                                                                                                                                                                                   
                  
      // Fallback: show nothing if lookup fails                                                                                                                                                           
      return 'sys_idISEMPTY';
  })()

javascript:(function() {
      // Get the Source Table reference (points to Config Class Mapping)                                                                                                                                  
      var classMappingId = current.source_table;                                                                                                                                                          
  
      // If no Source Table selected, show nothing                                                                                                                                                        
      if (gs.nil(classMappingId)) {
          return 'sys_idISEMPTY';                                                                                                                                                                         
      }           

      // Look up Config Class Mapping to get actual table name
      var classMappingGr = new GlideRecord('x_illu2_illumio_illumio_config_class_mapping');
      if (classMappingGr.get(classMappingId)) {                                                                                                                                                           
          var tableName = classMappingGr.getValue('source_table');
                                                                                                                                                                                                          
          // Filter sys_dictionary: fields from this table, exclude system/collection fields                                                                                                              
          return 'name=' + tableName + '^elementISNOTEMPTY^internal_type!=collection';                                                                                                                    
      }                                                                                                                                                                                                   
                  
      // Fallback: show nothing                                                                                                                                                                           
      return 'sys_idISEMPTY';
  })()
